from fastapi import Depends, FastAPI
app = FastAPI()
def sub(q: str = None):
    return q
def dep(s=Depends(sub), page: int = 1):
    return s
@app.get('/items')
def items(d=Depends(dep), x: int = 0):
    return d
print(sorted(p['name'] for p in app.openapi()['paths']['/items']['get']['parameters']))
